import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";

import { caretDown, caretRight } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

function isTreeItem(node: HbrTreeItem | HTMLElement) {
	return node instanceof HTMLElement && node.tagName === "HBR-TREE-ITEM";
}

/**
 * @summary A tree item serves as a hierarchical node that lives inside a [tree](/components/tree).
 *
 * @event hbr-expand - Emitted when the tree item expands.
 * @event hbr-after-expand - Emitted after the tree item expands and all animations are complete./zx,,/z,x/z,x.z?x./.
 * @event hbr-collapse - Emitted when the tree item collapses.
 * @event hbr-after-collapse - Emitted after the tree item collapses and all animations are complete.
 * @event hbr-lazy-change - Emitted when the tree item's lazy state changes.
 * @event hbr-lazy-load - Emitted when a lazy item is selected. Use this event to asynchronously load data and append
 *  items to the tree before expanding. After appending new items, remove the `lazy` attribute to remove the loading
 *  state and update the tree.
 *
 * @slot - The default slot.
 * @slot expand-icon - The icon to show when the tree item is expanded.
 * @slot collapse-icon - The icon to show when the tree item is collapsed.
 *
 * @csspart base - The component's base wrapper.
 * @csspart item - The tree item's container. This element wraps everything except slotted tree item children.
 * @csspart item--disabled - Applied when the tree item is disabled.
 * @csspart item--expanded - Applied when the tree item is expanded.
 * @csspart item--indeterminate - Applied when the selection is indeterminate.
 * @csspart item--selected - Applied when the tree item is selected.
 * @csspart indentation - The tree item's indentation container.
 * @csspart expand-button - The container that wraps the tree item's expand button and spinner.
 * @csspart spinner - The spinner that shows when a lazy tree item is in the loading state.
 * @csspart spinner__base - The spinner's base part.
 * @csspart label - The tree item's label.
 * @csspart children - The container that wraps the tree item's nested children.
 * @csspart checkbox - The checkbox that shows when using multiselect.
 * @csspart checkbox__base - The checkbox's exported `base` part.
 * @csspart checkbox__control - The checkbox's exported `control` part.
 * @csspart checkbox__control--checked - The checkbox's exported `control--checked` part.
 * @csspart checkbox__control--indeterminate - The checkbox's exported `control--indeterminate` part.
 * @csspart checkbox__checked-icon - The checkbox's exported `checked-icon` part.
 * @csspart checkbox__indeterminate-icon - The checkbox's exported `indeterminate-icon` part.
 * @csspart checkbox__label - The checkbox's exported `label` part.
 *
 * @data-testid default-expand-button - The default expand button when the item is collapsed.
 * @data-testid default-collapse-button - The default collapse button when the item is expanded.
 */

@Component({
	tag: "hbr-tree-item",
	styleUrl: "tree-item.scss",
	shadow: true,
})
export class HbrTreeItem {
	@Element() host: HTMLHbrTreeItemElement;

	// private readonly localize = new LocalizeController(this);

	@Prop({ reflect: false, mutable: true }) indeterminate = false;
	@Prop({ reflect: false, mutable: true }) leaf = false;
	@Prop({ reflect: false, mutable: true }) loading = false;
	/** @internal */
	@Prop({ reflect: false, mutable: true }) selectable = false;

	/** Expands the tree item. */
	@Prop({ reflect: true }) expanded = false;

	/** Draws the tree item in a selected state. */
	@Prop({ reflect: true }) selected = false;

	/** Prevents user from selecting or unselecting the tree-item */
	@Prop({ reflect: true }) unselectable = false;

	/** Disables the tree item. */
	@Prop({ reflect: true }) disabled = false;

	/** Enables lazy loading behavior. */
	@Prop({ reflect: true }) lazy = false;

	/**
	 * Indicates the item has children hidden by an active search/filter. When set,
	 * the tree will not recompute this parent's `selected`/`indeterminate` state from
	 * its visible children alone, so the consumer-controlled state (derived from the
	 * full data set) is preserved.
	 */
	@Prop({ reflect: true }) filtered = false;

	@Prop() dataId = "";

	@Prop() aria = {
		expandButtonLabel: "Expand tree item",
		collapseButtonLabel: "Collapse tree item",
	};

	/** Determines where the expand/collapse icon is placed. */
	@Prop({ reflect: false }) triggerPosition: "start" | "end" = "start";

	/** Emitted when the tree item begins to collapse. */
	@Event({ eventName: "hbr-collapse" }) hbrCollapse: EventEmitter;

	/** Emitted after the tree item collapses */
	@Event({ eventName: "hbr-after-collapse" }) hbrAfterCollapse: EventEmitter;

	/** Emitted when the tree item begins to expand. */
	@Event({ eventName: "hbr-expand" }) hbrExpand: EventEmitter;

	/** Emittend after the tree item expands */
	@Event({ eventName: "hbr-after-expand" }) hbrAfterExpand: EventEmitter;

	/** Emitted when the tree item lazily loaded */
	@Event({ eventName: "hbr-lazy-load" }) hbrLazyLoad: EventEmitter;

	/** Emittend after the tree item lazily changes */
	@Event({ eventName: "hbr-lazy-change" }) hbrLazyChange: EventEmitter;

	@State() selectionMode: "single" | "multiple" | "leaf" = "single";

	@State() size: "small" | "medium" = "medium";

	@State() interactiveSlotContent = false;

	@State() variant: undefined | "tab" = undefined;

	// defaultSlot: Element;
	childrenSlot: Element;
	// itemElement: HTMLDivElement;
	// childrenContainer: HTMLDivElement;

	connectedCallback() {
		this.handleChildrenSlotChange = this.handleChildrenSlotChange.bind(this);
		this.handleInteractiveSlotChange =
			this.handleInteractiveSlotChange.bind(this);
		if (this.isNestedItem()) {
			this.host.slot = "children";
		}
	}

	componentDidLoad() {
		// this.childrenContainer = this.host.shadowRoot.querySelector(
		// 	".tree-item__children",
		// );
		this.childrenSlot = this.host.shadowRoot.querySelector(
			"slot[name=children]",
		);
		// this.childrenContainer.hidden = !this.expanded;
		// this.childrenContainer.style.height = this.expanded ? "auto" : "0";

		this.leaf = !this.lazy && this.getChildrenItems().length === 0;
		this.handleExpandedChange();
		this.setSelectionMode();
		this.setSize();
		this.setVariant();
		// Initialize interactive slot presence once component has mounted
		this.handleInteractiveSlotChange();
	}

	componentDidUpdate() {
		this.setSelectionMode();
		this.setSize();
		this.setVariant();
	}

	private async animateCollapse() {
		this.hbrCollapse.emit();

		// await stopAnimations(this.childrenContainer);

		// const { keyframes, options } = getAnimation(this, 'tree-item.collapse', {
		//     // dir: this.localize.dir()
		//     dir: "ltr"
		// });
		// await animateTo(
		//     this.childrenContainer,
		//     shimKeyframesHeightAuto(keyframes, this.childrenContainer.scrollHeight),
		//     options
		// );
		// this.childrenContainer.hidden = true;
		// this.childrenContainer.style.height = "0";
		this.hbrAfterCollapse.emit();
	}

	// Checks whether the item is nested into an item
	private isNestedItem(): boolean {
		const parent = this.host.parentElement;
		return !!parent && isTreeItem(parent);
	}

	private setSelectionMode = (): void => {
		const hbrTree = this.host.closest("hbr-tree");
		if (hbrTree) {
			this.selectionMode = hbrTree.selection;
		}
	};

	private setSize = (): void => {
		const hbrTree = this.host.closest("hbr-tree");
		if (hbrTree) {
			this.size = hbrTree.size;
		}
	};

	private setVariant = (): void => {
		const hbrTree = this.host.closest("hbr-tree");
		if (hbrTree) {
			this.variant = hbrTree.variant;
		}
	};

	private handleChildrenSlotChange() {
		this.loading = false;
		this.leaf = !this.lazy && this.getChildrenItems().length === 0;
	}

	private handleInteractiveSlotChange() {
		const slot = this.host.shadowRoot.querySelector(
			'slot[name="interactive"]',
		) as HTMLSlotElement | null;
		let assigned: Element[] = [];
		if (slot) {
			assigned = slot.assignedElements({ flatten: true }).filter((el) => {
				// If a nested slot is present, consider it only if it has assigned elements itself
				if (el.tagName === "SLOT") {
					const nested = (el as HTMLSlotElement).assignedElements({
						flatten: true,
					});
					return nested.length > 0;
				}
				return true;
			});
		}

		this.interactiveSlotContent = assigned.length > 0;

		// Setting the height of slotted action dropdown (applies to nested hbr-button)
		assigned.forEach((el) => {
			const nested = el.querySelector("hbr-button");
			if (nested) {
				nested.style.setProperty("--hbr-control-height-xs", "24px");
			}
		});
	}

	private async animateExpand() {
		this.hbrExpand.emit();

		// await stopAnimations(this.childrenContainer);
		// this.childrenContainer.hidden = false;

		// const { keyframes, options } = getAnimation(this, 'tree-item.expand', {
		//     // dir: this.localize.dir()
		//     dir: "ltr"
		// });
		// await animateTo(
		//     this.childrenContainer,
		//     shimKeyframesHeightAuto(keyframes, this.childrenContainer.scrollHeight),
		//     options
		// );
		// this.childrenContainer.style.height = "auto";
		this.hbrAfterExpand.emit();
	}

	@Watch("loading")
	handleLoadingChange() {
		this.host.setAttribute("aria-busy", this.loading ? "true" : "false");

		if (!this.loading) {
			this.animateExpand();
		}
	}

	@Watch("disabled")
	handleDisabledChange() {
		this.host.setAttribute("aria-disabled", this.disabled ? "true" : "false");
	}

	@Watch("selected")
	handleSelectedChange() {
		this.host.setAttribute("aria-selected", this.selected ? "true" : "false");
		this.indeterminate = false;
	}

	@Watch("expanded")
	handleExpandedChange() {
		if (!this.leaf) {
			this.host.setAttribute("aria-expanded", this.expanded ? "true" : "false");
		} else {
			this.host.removeAttribute("aria-expanded");
		}
	}

	@Watch("expanded")
	handleExpandAnimation() {
		if (this.expanded) {
			if (this.lazy) {
				this.loading = true;
				this.hbrLazyLoad.emit();
			} else {
				this.animateExpand();
			}
		} else {
			this.animateCollapse();
		}
	}

	@Watch("lazy")
	handleLazyChange() {
		this.hbrLazyChange.emit();
	}

	/** Gets all the nested tree items in this node. */
	getChildrenItems({
		includeDisabled = true,
	}: { includeDisabled?: boolean } = {}): HbrTreeItem[] {
		return this.childrenSlot
			? // @ts-ignore
			  ([...this.childrenSlot.assignedElements({ flatten: true })].filter(
					// @ts-ignore
					(item: HbrTreeItem) =>
						isTreeItem(item) && (includeDisabled || !item.disabled),
			  ) as HbrTreeItem[])
			: [];
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const showExpandButton = !this.loading && (!this.leaf || this.lazy);

		const aria = {
			"aria-busy": this.loading ? "true" : "false",
			"aria-disabled": this.disabled ? "true" : "false",
			"aria-selected": this.selected ? "true" : "false",
			"aria-expanded": this.expanded ? "true" : "false",
			"aria-label": this.dataId,
		};

		const checkboxAttributes: {
			checked?: boolean;
			indeterminate?: boolean;
			disabled?: boolean;
			size?: "small" | "medium";
		} = {};
		if (this.selected) checkboxAttributes.checked = true;
		if (this.indeterminate) checkboxAttributes.indeterminate = true;
		if (this.unselectable || this.disabled) checkboxAttributes.disabled = true;
		if (this.size) checkboxAttributes.size = this.size;

		const expandButton = (
			<div
				part="expand-button"
				class={{
					"tree-item__expand-button": true,
					"tree-item__expand-button--visible": showExpandButton,
					"tree-item__expand-button--start": this.triggerPosition === "start",
					"tree-item__expand-button--end": this.triggerPosition === "end",
				}}
			>
				{this.loading ? (
					<slot name="loading">
						<hbr-spinner part="spinner" exportparts="base:spinner__base" />
					</slot>
				) : null}

				<span class="tree-item__expand-icon-slot">
					<slot name="expand-icon">
						<hbr-icon-button
							class="tree-item__icon-button"
							asset={customSystemIcons?.["caret-right"] || caretRight}
							aria-label={this.aria.expandButtonLabel}
							exportparts="base:icon-button-base"
							tabIndex={-1}
							data-testid="default-expand-button"
						/>
					</slot>
				</span>
				<span class="tree-item__expand-icon-slot">
					<slot name="collapse-icon">
						<hbr-icon-button
							class="tree-item__icon-button"
							asset={customSystemIcons?.["caret-down"] || caretDown}
							aria-label={this.aria.collapseButtonLabel}
							exportparts="base:icon-button-base"
							tabIndex={-1}
							data-testid="default-collapse-button"
						/>
					</slot>
				</span>
			</div>
		);

		return (
			<Host role="treeitem" tabindex="-1" {...aria}>
				<div
					part="base"
					class={{
						"tree-item": true,
						"tree-item--expanded": this.expanded,
						"tree-item--selected": this.selected,
						"tree-item--disabled": this.disabled,
						"tree-item--leaf": this.leaf,
						"tree-item--has-expand-button": showExpandButton,
						// 'tree-item--rtl': this.localize.dir() === 'rtl'
						"tree-item--rtl": false,
					}}
				>
					<span
						class={{
							"tree-item__item-wrapper": true,
							"tree-item__item--unselectable": this.unselectable,
						}}
					>
						<div
							part="item"
							class={{
								"tree-item__item": true,
								"tree-item__item--selected--single":
									this.selected &&
									(this.selectionMode === "single" ||
										this.selectionMode === "leaf"),
								"tree-item__item--selected--multiple":
									this.selected && this.selectionMode === "multiple",
								"tree-item__item--sm": this.size === "small",
								"tree-item__item--md": this.size === "medium",
								"tree-item__item--tabs": this.variant === "tab",
								"tree-item__item--interactive-focus":
									this.interactiveSlotContent,
								"tree-item__item--focus": !this.interactiveSlotContent,
							}}
							// ref={(el) => {
							// 	this.itemElement = el;
							// }}
						>
							<div class="tree-item__indentation" part="indentation" />

							{this.triggerPosition === "start" ? expandButton : null}

							{this.selectable ? (
								<hbr-checkbox
									part="checkbox"
									exportparts="
								element,
								input,
								label,
								error-icon-wrapper,
								error-icon,
								default-icon-wrapper,
								default-icon,
								checked-icon-wrapper,
								checked-icon,
								indeterminate-icon-wrapper,
								indeterminate-icon,
								base:checkbox-base,
								content:checkbox-content,
								content-checked:checkbox-content-checked,
								control:checkbox-control,
								control-focus:checkbox-control-focus,
								
						"
									class={{
										"tree-item__checkbox": true,
										"tree-item__checkbox--unselectable": this.unselectable,
										"tree-item__checkbox--selected--unselectable":
											this.selected && this.unselectable,
										"tree-item__checkbox--indeterminate--unselectable":
											this.indeterminate,
									}}
									{...checkboxAttributes}
									tabindex="-1"
								>
									<span class="tree-item__label" part="label">
										<slot />
									</span>
								</hbr-checkbox>
							) : (
								<span
									class={{
										"tree-item__label": true,
										"tree-item__label-sm": this.size === "small",
										"tree-item__label-md": this.size === "medium",
										"tree-item__label--unselectable": this.unselectable,
										"tree-item__label--single": this.selectionMode === "single",
									}}
									part="label"
								>
									<slot />
								</span>
							)}
							<span
								class={{
									"tree-item__suffix": true,
									"tree-item__suffix-sm": this.size === "small",
									"tree-item__suffix-md": this.size === "medium",
								}}
							>
								<slot name="suffix" />
							</span>

							{this.triggerPosition === "end" ? expandButton : null}
						</div>

						<div
							class={{
								"tree-item__interactive": true,
								"tree-item__interactive-sm": this.size === "small",
								"tree-item__interactive-md": this.size === "medium",
							}}
							part="interactive"
							hidden={!this.interactiveSlotContent}
							aria-hidden={this.interactiveSlotContent ? "false" : "true"}
						>
							<slot
								name="interactive"
								onSlotchange={this.handleInteractiveSlotChange}
							/>
						</div>
					</span>

					<div
						class={{
							"tree-item__children": true,
							"tree-item__children-sm": this.size === "small",
							"tree-item__children-md": this.size === "medium",
						}}
						hidden={!this.expanded}
						style={{
							height: this.expanded ? "auto" : "0",
						}}
						part="children"
						role="group"
					>
						<slot
							name="children"
							onSlotchange={this.handleChildrenSlotChange}
						/>
					</div>
				</div>
			</Host>
		);
	}
}

